            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(content: Text('虚拟IP地址和本地IP冲突[$configName]')),
            );
            break;
          default:
            _closeVnt(itemKey);
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(content: Text('未知错误 ${msg.msg} [$configName]')),
            );
