          debugPrint('iOS: ===== EXTENSION LOG DELTA END =====');
        }
        _lastExtensionLogSnapshot = extLog;
      }
    } catch (e) {
      debugPrint('iOS: readExtensionLog polling error: $e');
    }
    if (_extensionLogPollTicks >= 30) {
      _stopExtensionLogPolling();
    }
  });
