    let mut buf = [0; BUFFER_SIZE];
    let mut extend = [0; BUFFER_SIZE];
    let fd = device.as_tun_fd();
    fd.set_nonblock()?;
    SourceFd(&fd.as_raw_fd()).register(poll.registry(), FD, Interest::READABLE)?;
    let mut events = Events::with_capacity(4);
    #[cfg(not(target_os = "macos"))]
    let start = 12;
    // macOS utun includes a 4-byte protocol header, so we start at offset 8
    // to leave room for the vnt 12-byte header (first 4 bytes overlap with utun header,
    // which gets zeroed by buf[..12].fill(0) afterwards).
    // iOS uses pipes instead of utun direct access, so no utun header — same as Linux.
    #[cfg(target_os = "macos")]
    let start = 12 - 4;
    loop {
        if let Err(e) = poll.poll(&mut events, None) {
            crate::ignore_io_interrupted(e)?;
            continue;
        }
        for event in events.iter() {
            if event.token() == STOP {
                return Ok(());
            }
            let mut retries = 0;
            loop {
                let len = match fd.read(&mut buf[start..]) {
                    Ok(len) => len + start,
                    Err(e) => {
                        if e.kind() == io::ErrorKind::WouldBlock {
                            retries += 1;
                            if retries < 8 {
                                continue;
                            }
                            break;
                        }
                        Err(e)?
                    }
                };
                // buf是重复利用的，需要重置头部
                buf[..12].fill(0);
